      "text": "覚は十三回目の鐘を追うことをやめた。啓吾も最後には、怪異を暴くより現実側の被害を減らす道を選ぶ。\n\n凛の記憶は完全には戻らなかったが、兄妹は新しい関係を一から作り直した。\n\n時計塔は封鎖され、十三時の噂はやがて都市伝説へ戻っていく。\n\n真実へ届かなかった代わりに、彼らは十二時までの世界で生き続けた。",
