      "speaker": "鳴海 覚",
      "text": "廊下へ出ると呼吸が楽になった。ドアの向こうで澪が一人、雨の記憶に耐えている。\n\n数分後に戻ったとき、澪は「大丈夫」とだけ言った。黒い靄は前より濃い。",
