      "text": "原文には、図書館の目的が記されていた。\n\n“人が耐えられない記憶を一時的に預かり、再び抱えられる日まで保管する”。\n\n本来、忘却は永久消去ではなかった。歴代司書の改変で「消す場所」へ変質したのだ。",
