      "chapter": 1,
      "chapterTitle": "第一章　黒い靄の正体",
      "bg": "library",
      "speaker": "鳴海 覚",
      "text": "白は否定しなかった。むしろ少しだけ安心したように、澪の本へ視線を戻した。",
